    h += `<tr><td style="padding:12px 22px 18px;${F}font-size:11.5px;color:#94a3b8;border-top:1px solid #e5eaf1;">Red = at least one unit in breakdown · green 0 = all working · · = nothing posted. Sent from ORBIT · ${new Date().toLocaleString()}</td></tr></table></td></tr></table>`;
    const rows = det.map(x => [L, x.w, x.g, x.t == null ? '' : x.t, x.wk == null ? '' : x.wk, x.b, remOf(L, x.g, x.w).map(y => y.t).join(' | ')]);
