    window.extMailData = () => m; wMail_open('ext');
    /* default recipients: the Fleet Dept users (job title / profile / BU / department mentions "fleet"), else the Fleet recipients last used on the Fleet pages */
    const w = Q('#wMailModal'), toI = w && w.querySelector('#wMailTo'), ccI = w && w.querySelector('#wMailCc'), ok = v => { const e = typeof orbEmailOf === 'function' ? orbEmailOf(v) : String(v || ''); return /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e) ? e : ''; };
    const fl = (typeof users !== 'undefined' && users.list || []).filter(u => u && !u.builtin && ok(u.email) && /fleet/i.test([u.jobTitle, u.spProfile, u.bu, u.department, u.dept, u.title, u.whName].join(' '))), to = new Map(), cc = new Map();
    fl.forEach(u => to.set(ok(u.email).toLowerCase(), ok(u.email)));
