    (typeof users !== 'undefined' && users.list || []).forEach(u => { if (!u || u.builtin) return; const em = mail(u.email); if (!em) return;
      const byName = u.whName && String(u.whName).split(/[\/,;]/).some(x => nn.has(nz(x.trim()))), byId = u.role !== 'admin' && !locAll(u) && locIds(u).some(i => ids.has(String(+i || i)));
      if (!byName && !byId) return; if (!to.has(em.toLowerCase())) { to.set(em.toLowerCase(), em); who.push(u.displayName || u.username); } const m = mail(u.managerEmail || u.lineMngr); if (m) cc.set(m.toLowerCase(), m); });
