    if (!r.to.length) { set('⚠ No user is linked to these warehouse(s) — add the Warehouse name / Location ID on the Users page, or type the recipients in "To".', 'warn'); return; }
    if (toI) { toI.value = r.to.join(', '); toI.dispatchEvent(new Event('input', { bubbles: true })); } if (ccI) { ccI.value = r.cc.join(', '); ccI.dispatchEvent(new Event('input', { bubbles: true })); }
